using Fgs.Foundation.Paging;
namespace Fgs.Asset.Infrastructure.AssetWarranties;
internal static class FgsAssetWarrantySql { public const string Table = "asset.\"FgsAssetWarranty\""; public const string SelectDetailColumns = "\"Id\", \"AssetId\", \"WarrantyType\", \"WarrantyProvider\", \"WarrantyNumber\", \"RegistrationNumber\", \"StartDate\", \"EndDate\", \"CoverageDescription\""; public const string SelectSummaryColumns = SelectDetailColumns; public const string SelectLookupColumns = "\"Id\", \"WarrantyType\", \"StartDate\", \"EndDate\""; private static readonly HashSet<string> AllowedSortColumns = new(StringComparer.OrdinalIgnoreCase) { "Id", "AssetId", "WarrantyType", "StartDate", "EndDate" }; public static string ResolveOrderBy(string? sortBy, SortDirection direction) { var dir = direction == SortDirection.Desc ? "DESC" : "ASC"; if (string.IsNullOrWhiteSpace(sortBy) || !AllowedSortColumns.Contains(sortBy)) return $"ORDER BY \"Id\" {dir}"; return $"ORDER BY \"{AllowedSortColumns.First(c => c.Equals(sortBy, StringComparison.OrdinalIgnoreCase))}\" {dir}"; } }
